'use strict';

// Regression coverage for orders-null-coupon: POST /orders answered 500 when
// the body carried no coupon field. The coupon field is optional, so an absent
// code prices at full; a SUPPLIED but unusable code stays a client error.
//
// The HTTP cases go through the real composition root (createServer), which is
// where the defect was observable.

const { test, before, after } = require('node:test');
const assert = require('node:assert/strict');
const { createServer } = require('../src/server.js');
const { applyCoupon } = require('../src/coupons.js');

const NO_COUPON_PRICING = { coupon: null, discountPercent: 0 };

let server;
let baseUrl;

before(async () => {
  server = createServer();
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  baseUrl = `http://127.0.0.1:${server.address().port}`;
});

after(async () => {
  await new Promise((resolve) => server.close(resolve));
});

async function postOrder(rawJsonBody) {
  const response = await fetch(`${baseUrl}/orders`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: rawJsonBody,
  });
  return { status: response.status, body: await response.json() };
}

test('POST /orders prices at full when the body carries no coupon field', async () => {
  const { status, body } = await postOrder('{}');

  assert.equal(status, 200);
  assert.deepEqual(body, Object.assign({ id: 'ord-1' }, NO_COUPON_PRICING));
});

test('POST /orders prices at full when the coupon field is explicitly null', async () => {
  const { status, body } = await postOrder('{"coupon":null}');

  assert.equal(status, 200);
  assert.deepEqual(body, Object.assign({ id: 'ord-1' }, NO_COUPON_PRICING));
